import{_ as o,l as i,o as n,c as s,v as p,p as h,x as r,d as t,i as E,S as d,b as a}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"因子模型的贝叶斯比较","description":"","frontmatter":{"title":"因子模型的贝叶斯比较","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bayesian-factor-comparison.md","filePath":"quant/bayesian-factor-comparison.md","lastUpdated":1789023840000}'),B={name:"quant/bayesian-factor-comparison.md"};function c(m,e,u,A,S,f){const l=i("Mermaid");return n(),s("div",null,[e[1]||(e[1]=p('<h1 id="因子模型的贝叶斯比较" tabindex="-1">因子模型的贝叶斯比较 <a class="header-anchor" href="#因子模型的贝叶斯比较" aria-label="Permalink to &quot;因子模型的贝叶斯比较&quot;">​</a></h1><div class="epigraph"><p>比较的不是谁在一张表上把 $J$ 的 p 值抬过 5%，而是：在给定先验下，数据更愿意把概率质量分给哪一套因子。</p><footer>—— Barillas and Shanken, Comparing Asset Pricing Models, Journal of Finance, 2018</footer></div><p><a href="/quant/hj-distance-test">HJ 距离</a> 给出误设的样本范数，仍是经典点上的一次比较：不自动惩罚「多一个因子总能降 \\(\\delta\\)」。Barillas 与 Shanken 把因子模型比较写成贝叶斯：对嵌套与非嵌套的线性因子模型，用边际似然（或等价的 Sharpe 改进）算后验概率。本课缺口：在 GMM/HJ/GRS 都报过之后，<strong>用边缘似然处理多重模型与过拟合</strong>。下一课收缩把同一思想用到单个系数，而不是整套模型的胜负。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>候选模型 \\(\\mathcal{M}_k\\)：可交易因子 \\(f^{(k)}\\)，检验资产 \\(R\\)。经典做法逐个 GRS 或两两 \\(J\\)。模型数随因子动物园指数涨，5% 拒绝失去家庭wise 含义；嵌套时大模型总有更小的样本 \\(\\alpha\\)。问题是计算 \\(p(\\mathcal{M}_k\\mid R)\\)，先验 \\(p(\\mathcal{M}_k)\\) 与参数先验必须写明。</p><p>Barillas–Shanken 的关键简化：比较可交易因子模型，不必先指定检验资产——在一定先验下，模型比较约化成<strong>因子之间谁解释谁的夏普</strong>。这与「检验资产选得越好看越通过」的经典病相对。仍须声明：先验对 \\(\\alpha\\) 的尺度（Barillas–Shanken 用相对因子夏普的先验）会推动后验。</p><h3 id="不是把-p-值换成「贝叶斯」标签" tabindex="-1">不是把 p 值换成「贝叶斯」标签 <a class="header-anchor" href="#不是把-p-值换成「贝叶斯」标签" aria-label="Permalink to &quot;不是把 p 值换成「贝叶斯」标签&quot;">​</a></h3><p>BIC 近似边缘似然，惩罚参数个数，但是对先验与样本量的粗近似。资产定价 \\(T\\) 不算大、\\(N\\) 与 \\(K\\) 的相对大小敏感，应尽量用他们给出的精确或准精确边际似然，而不是随手 BIC。Harvey、Liu 与 Zhu 对因子动物园的多重检验是频率派 FDR；本课是模型空间上的后验。两者都在管「太多候选」，对象一个是单因子 t，一个是整模型。</p><p><span class="marginnote">后验概率 0.7 不表示「有 70% 把握在真实世界赚钱」。它是：在模型集封闭、先验与似然都接受的前提下，概率质量的分配。模型集没把真实包含进去，后验仍会在错误集里归一化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>似然。</strong> 通常假设因子与资产联合正态，或对超额收益的时间序列回归正态。边缘化 \\(\\beta,\\Sigma,\\lambda\\)。共轭先验给出解析或易算的边际似然。Barillas–Shanken 比较「谁该出现在定价因子里」，把非定价的检验资产与因子一并处理。</p><p><strong>先验。</strong> 对 \\(\\alpha\\) 的先验尺度是关键超参：太紧则任何 \\(\\alpha\\) 都被视为噪声，小模型胜；太松则数据无法反对大模型。应报告超参敏感性。均匀模型先验把概率平分给所有子集，因子多时大模型空间占优，可用稀释先验。</p><p><strong>输出。</strong> 每个模型的后验、因子的包含概率、以及相对基准（市场）的证据比。不要只报「最佳模型」点名。</p><h3 id="与-grs-对照" tabindex="-1">与 GRS 对照 <a class="header-anchor" href="#与-grs-对照" aria-label="Permalink to &quot;与 GRS 对照&quot;">​</a></h3><p>GRS 拒绝「这些 \\(\\alpha\\) 联合为零」。贝叶斯问「加入这些因子后边际似然是否上升」。可以 GRS 拒绝（经典显著 \\(\\alpha\\)）但贝叶斯仍支持小模型（\\(\\alpha\\) 幅度相对先验与 \\(\\Sigma\\) 不够）。这不是矛盾：一个控 I 类错误，一个做模型选择。报告应并列，而不是用后验抹掉拒绝。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>边缘似然 \\(\\int p(R\\mid\\theta,\\mathcal{M})p(\\theta\\mid\\mathcal{M})d\\theta\\) 自动把只会拟合噪声的参数积掉——Ockham 因子。夏普改进大、且稳定，才会胜过额外维度的惩罚。机制与 Hjort–Claeskens 模型平均、与经验贝叶斯收缩同源：都把「额外自由」写成先验下的积分，而不是只看样本内平方误差。</p><p>可交易因子比较能约化，是因为线性定价下，模型的优劣由因子张成的前沿决定。宏观因子不可交易时，约化失败，必须回到检验资产与 SDF，经典 HJ/GMM 更直。</p><p><span class="marginnote">正态似然对危机日敏感。用 t 似然或混合会改后验。若结论只在正态下成立，应写明。这与稳健回归课将处理的离群是同一尾巴，只是这里作用在模型概率上。</span></p><h3 id="计算" tabindex="-1">计算 <a class="header-anchor" href="#计算" aria-label="Permalink to &quot;计算&quot;">​</a></h3><p>子集 \\(2^K\\) 在 \\(K\\gt 20\\) 时不可枚举，用 MCMC、鸟击、或只比较预登记的嵌套链（市场 / FF3 / FF5 / Q）。探索性的全子集搜索要把多重比较写进发现研究，不能当验证。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>样本分裂：用一半算后验、一半验证，先验仍会泄漏若你用全历史选因子名单。因子是被同一文献矿出来的，后验过乐观——这是 Harvey–Liu–Zhu 的频率派警告在贝叶斯里的对应：先验应对「已发表」打折，很少有人真这么做，故后验应当上界。</p><p>工程：预登记模型集与 \\(\\alpha\\) 先验尺度；报包含概率与敏感性；并列 GRS/HJ。不要用后验概率当组合权重除非明确模型平均并扣成本。不要把宏观 SDF 塞进 Barillas–Shanken 的可交易约化。下一课把收缩从「整模型」降到「单个 \\(\\beta\\) 与均值」。</p>',24)),(n(),h(d,null,{default:r(()=>[E(l,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E5%80%99%E9%80%89%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%E9%9B%86%22%5D%20--%3E%20LIK%5B%22%E8%BE%B9%E9%99%85%E4%BC%BC%E7%84%B6%22%5D%0A%20%20PR%5B%22%CE%B1%20%E4%B8%8E%E6%A8%A1%E5%9E%8B%E5%85%88%E9%AA%8C%22%5D%20--%3E%20LIK%0A%20%20LIK%20--%3E%20POST%5B%22%E5%90%8E%E9%AA%8C%20p(M%7C%E6%95%B0%E6%8D%AE)%22%5D%0A%20%20POST%20--%3E%20INC%5B%22%E5%9B%A0%E5%AD%90%E5%8C%85%E5%90%AB%E6%A6%82%E7%8E%87%22%5D%0A%20%20GRS%5B%22GRS%20%2F%20HJ%22%5D%20--%3E%20CLASS%5B%22%E9%A2%91%E7%8E%87%E6%B4%BE%E6%8B%92%E7%BB%9D%E4%B8%8E%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20POST%20--%3E%20NOTE%5B%22%E9%80%89%E6%8B%A9%20vs%20%E6%A3%80%E9%AA%8C%20%E4%B8%8D%E4%BA%92%E7%9B%B8%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20CLASS%20--%3E%20NOTE%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"贝叶斯模型比较用边缘似然分配后验，惩罚只拟合样本 \\(\\alpha\\) 的额外因子。"),a("li",null,"Barillas–Shanken 在可交易因子、合适先验下把比较约化到因子夏普，减轻检验资产挑选。"),a("li",null,"先验尺度与模型集封闭性决定后验；应做敏感性，并与 GRS/HJ 并列。"),a("li",null,"不可交易宏观因子不能套同一约化；因子动物园的选择偏差会让后验偏乐观。"),a("li",null,[t("出处：Barillas and Shanken, "),a("em",null,"Journal of Finance"),t(", 2018；相关贝叶斯资产定价见 Avramov 等；多重检验的频率派对照见 Harvey, Liu and Zhu。")])],-1))])}const g=o(B,[["render",c]]);export{k as __pageData,g as default};
